/* Heritage Athletic Club - shadcn-style theme tokens for the member site (published to 21st.dev) */
:root {
  --background: #F4EEE1;
  --foreground: #1B2233;
  --card: #FBF8F1;
  --card-foreground: #1B2233;
  --popover: #FBF8F1;
  --popover-foreground: #1B2233;
  --primary: #14213D;
  --primary-foreground: #F4EEE1;
  --secondary: #EAE0CB;
  --secondary-foreground: #14213D;
  --muted: #EAE0CB;
  --muted-foreground: #5F5A4E;
  --accent: #C9A45C;
  --accent-foreground: #14213D;
  --destructive: #7A1F26;
  --destructive-foreground: #FBF8F1;
  --border: #DDD2BA;
  --input: #DDD2BA;
  --ring: #B08D57;
  --chart-1: #14213D;
  --chart-2: #B08D57;
  --chart-3: #1F5A3E;
  --chart-4: #7A1F26;
  --chart-5: #E3A33B;
  --radius: 0.875rem;
  --sidebar: #14213D;
  --sidebar-foreground: #F4EEE1;
  --sidebar-primary: #C9A45C;
  --sidebar-primary-foreground: #14213D;
  --sidebar-accent: #1F3260;
  --sidebar-accent-foreground: #E9CF8F;
  --sidebar-border: #2B3A5C;
  --sidebar-ring: #C9A45C;
}
.dark {
  --background: #0F1A2E;
  --foreground: #F4EEE1;
  --card: #14213D;
  --card-foreground: #F4EEE1;
  --popover: #14213D;
  --popover-foreground: #F4EEE1;
  --primary: #C9A45C;
  --primary-foreground: #14213D;
  --secondary: #1F3260;
  --secondary-foreground: #F4EEE1;
  --muted: #1A2846;
  --muted-foreground: #B9B09E;
  --accent: #E9CF8F;
  --accent-foreground: #14213D;
  --destructive: #C0505A;
  --destructive-foreground: #F4EEE1;
  --border: #2B3A5C;
  --input: #2B3A5C;
  --ring: #C9A45C;
  --chart-1: #C9A45C;
  --chart-2: #E9CF8F;
  --chart-3: #4FA27A;
  --chart-4: #C0505A;
  --chart-5: #E3A33B;
  --radius: 0.875rem;
  --sidebar: #0D1730;
  --sidebar-foreground: #F4EEE1;
  --sidebar-primary: #C9A45C;
  --sidebar-primary-foreground: #14213D;
  --sidebar-accent: #1F3260;
  --sidebar-accent-foreground: #E9CF8F;
  --sidebar-border: #2B3A5C;
  --sidebar-ring: #C9A45C;
}
